                     b = t4c_excits(idet,2); d = t4c_excits(idet,4); i = t4c_excits(idet,5); k = t4c_excits(idet,7); l = t4c_excits(idet,8);
                     IX = 0.0d0
                     do u = 1, nua
                        IX(:) = IX(:) + (1d0 * t2b(u,d,i,l)) * H2B_vovo_1023(:,b,u,k)
                     end do
                     do idet = toff(kdx), toff(kdx+1)-1
                        a = t4c_excits(idet,1); c = t4c_excits(idet,3); j = t4c_excits(idet,6);
                        val = 0.0d0
