                        a = t4c_excits(idet,1); c = t4c_excits(idet,3); i = t4c_excits(idet,5);
                        val = 0.0d0
                        do x = 1, nob
                           val = val + IX(x) * t2b(a,c,i,x)
                        end do
                        resid(idet) = resid(idet) - 1d0 * val
                     end do
                     ! -0.5 * W(axickl) * tab(bdjx), q = (b,d,j,k,l), sign -1
                     idet = toff(kdx)
                     b = t4c_excits(idet,2); d = t4c_excits(idet,4); j = t4c_excits(idet,6); k = t4c_excits(idet,7); l = t4c_excits(idet,8);
                     IX = 0.0d0
                     do u = 1, nub
                        IX(:) = IX(:) + (1d0 * t2c(d,u,k,l)) * H2B_voov_1023(:,b,j,u)
                     end do
                     do idet = toff(kdx), toff(kdx+1)-1
                        a = t4c_excits(idet,1); c = t4c_excits(idet,3); i = t4c_excits(idet,5);
                        val = 0.0d0
                        do x = 1, nob
                           val = val + IX(x) * t2b(a,c,i,x)
                        end do
                        resid(idet) = resid(idet) + 1d0 * val
                     end do
                     ! -1 * W(bxlcjk) * tab(adix), q = (b,d,j,k,l), sign +1
                     idet = toff(kdx)
                     b = t4c_excits(idet,2); d = t4c_excits(idet,4); j = t4c_excits(idet,6); k = t4c_excits(idet,7); l = t4c_excits(idet,8);
                     IX = 0.0d0
                     do u = 1, nua
                        IX(:) = IX(:) + (1d0 * t2b(u,d,j,l)) * H2B_vovo_1023(:,b,u,k)
                     end do
                     do idet = toff(kdx), toff(kdx+1)-1
                        a = t4c_excits(idet,1); c = t4c_excits(idet,3); i = t4c_excits(idet,5);
                        val = 0.0d0
                        do x = 1, nob
                           val = val + IX(x) * t2b(a,c,i,x)
