                        a = t4c_excits(idet,1); c = t4c_excits(idet,3); i = t4c_excits(idet,5);
                        val = 0.0d0
                        do x = 1, nob
                           val = val + IX(x) * t2b(a,c,i,x)
                        end do
                        resid(idet) = resid(idet) + 1d0 * val
                     end do
                     ! +0.25 * W(xklbcj) * tab(adix), q = (b,d,j,k,l), sign -1
                     idet = toff(kdx)
                     b = t4c_excits(idet,2); d = t4c_excits(idet,4); j = t4c_excits(idet,6); k = t4c_excits(idet,7); l = t4c_excits(idet,8);
                     IX = 0.0d0
                     do u = 1, nob
                        IX(:) = IX(:) + (1d0 * t2b(b,d,j,u)) * H2C_oooo_1023(:,u,k,l)
