                     lk(7) = pspace_find(sidx(24)%key, sidx(24)%nblock, pspace_key((/a,c,i,j,k/), 5, sidx(24)%dims, sidx(24)%chain))
                     lk(8) = pspace_find(sidx(25)%key, sidx(25)%nblock, pspace_key((/a,c,i,j,k/), 5, sidx(25)%dims, sidx(25)%chain))
                     lk(9) = pspace_find(sidx(26)%key, sidx(26)%nblock, pspace_key((/a,c,i,j,k/), 5, sidx(26)%dims, sidx(26)%chain))
                     lk(10) = pspace_find(sidx(27)%key, sidx(27)%nblock, pspace_key((/a,c,i,j,k/), 5, sidx(27)%dims, sidx(27)%chain))
                     lk(11) = pspace_find(sidx(28)%key, sidx(28)%nblock, pspace_key((/a,c,i,j,k/), 5, sidx(28)%dims, sidx(28)%chain))
                     lk(12) = pspace_find(sidx(29)%key, sidx(29)%nblock, pspace_key((/a,c,i,j,k/), 5, sidx(29)%dims, sidx(29)%chain))
                     lk(13) = pspace_find(sidx(30)%key, sidx(30)%nblock, pspace_key((/a,c,i,j,k/), 5, sidx(30)%dims, sidx(30)%chain))
                     lk(14) = pspace_find(sidx(31)%key, sidx(31)%nblock, pspace_key((/a,c,i,j,k/), 5, sidx(31)%dims, sidx(31)%chain))
                     lk(15) = pspace_find(sidx(32)%key, sidx(32)%nblock, pspace_key((/a,c,i,j,k/), 5, sidx(32)%dims, sidx(32)%chain))
                     lk(16) = pspace_find(sidx(33)%key, sidx(33)%nblock, pspace_key((/a,c,i,j,k/), 5, sidx(33)%dims, sidx(33)%chain))
                     lk(17) = pspace_find(sidx(34)%key, sidx(34)%nblock, pspace_key((/a,c,i,j,k/), 5, sidx(34)%dims, sidx(34)%chain))
                     ! -1 * W(axidjl) * tab(bcxk), q = (a,c,i,j,k), sign +1
                     idet = toff(kdx)
                     a = t4c_excits(idet,1); c = t4c_excits(idet,3); i = t4c_excits(idet,5); j = t4c_excits(idet,6); k = t4c_excits(idet,7);
                     IX = 0.0d0
                     do u = 1, nua
                        IX(:) = IX(:) + (1d0 * t2b(u,c,j,k)) * H2A_voov_1023(:,a,i,u)
                     end do
                     do idet = toff(kdx), toff(kdx+1)-1
                        b = t4c_excits(idet,2); d = t4c_excits(idet,4); l = t4c_excits(idet,8);
                        val = 0.0d0
                        do x = 1, noa
                           val = val + IX(x) * t2b(b,d,x,l)
                        end do
                        resid(idet) = resid(idet) - 1d0 * val
                     end do
                     ! -1 * W(axidjl) * tab(bcxk), q = (a,c,i,j,k), sign -1
                     idet = toff(kdx)
                     a = t4c_excits(idet,1); c = t4c_excits(idet,3); i = t4c_excits(idet,5); j = t4c_excits(idet,6); k = t4c_excits(idet,7);
                     IX = 0.0d0
                     do u = 1, nua
