                     idet = toff(kdx)
                     a = t4c_excits(idet,1); c = t4c_excits(idet,3); i = t4c_excits(idet,5); j = t4c_excits(idet,6); k = t4c_excits(idet,7);
                     IX = 0.0d0
                     do u = 1, nub
                        IX(:) = IX(:) + (1d0 * t2b(a,u,i,k)) * H2B_ovov(:,c,j,u)
                     end do
                     do idet = toff(kdx), toff(kdx+1)-1
                        b = t4c_excits(idet,2); d = t4c_excits(idet,4); l = t4c_excits(idet,8);
                        val = 0.0d0
