                  tchain(1:5) = (/.false.,.false.,.false.,.true.,.false./)
                  call sort_pspace(t4c_excits, t4c_amps, n4aabb, 5, (/1,4,5,6,7/), tdims, tchain, tnblk, tkey, toff, resid)
