                     a = t4c_excits(idet,1); d = t4c_excits(idet,4); i = t4c_excits(idet,5); j = t4c_excits(idet,6); k = t4c_excits(idet,7);
                     IX = 0.0d0
                     do u = 1, nob
                        IX(:) = IX(:) + (1d0 * t2b(a,d,j,u)) * H2B_oooo(:,u,i,k)
                     end do
                     do idet = toff(kdx), toff(kdx+1)-1
                        b = t4c_excits(idet,2); c = t4c_excits(idet,3); l = t4c_excits(idet,8);
                        val = 0.0d0
                        do x = 1, noa
                           val = val + IX(x) * t2b(b,c,x,l)
                        end do
                        resid(idet) = resid(idet) + 1d0 * val
