                     IX = 0.0d0
                     do u = 1, nub
                        IX(:) = IX(:) + (1d0 * t2b(a,u,j,l)) * H2B_ovov(:,d,i,u)
                     end do
                     do idet = toff(kdx), toff(kdx+1)-1
                        b = t4c_excits(idet,2); c = t4c_excits(idet,3); k = t4c_excits(idet,7);
                        val = 0.0d0
                        do x = 1, noa
                           val = val + IX(x) * t2b(b,c,x,k)
                        end do
                        resid(idet) = resid(idet) + 1d0 * val
                     end do
                     ! -1 * W(xdjail) * tab(bcxk), q = (a,d,i,j,l), sign +1
                     idet = toff(kdx)
                     a = t4c_excits(idet,1); d = t4c_excits(idet,4); i = t4c_excits(idet,5); j = t4c_excits(idet,6); l = t4c_excits(idet,8);
                     IX = 0.0d0
