                     end do
                     ! +1 * W(xikbcj) * tab(adxl), q = (a,d,i,j,l), sign -1
                     idet = toff(kdx)
                     a = t4c_excits(idet,1); d = t4c_excits(idet,4); i = t4c_excits(idet,5); j = t4c_excits(idet,6); l = t4c_excits(idet,8);
                     IX = 0.0d0
                     do u = 1, nob
                        IX(:) = IX(:) + (1d0 * t2b(a,d,j,u)) * H2B_oooo(:,u,i,l)
