                     lk(11) = pspace_find(sidx(28)%key, sidx(28)%nblock, pspace_key((/b,c,i,j,l/), 5, sidx(28)%dims, sidx(28)%chain))
                     lk(12) = pspace_find(sidx(29)%key, sidx(29)%nblock, pspace_key((/b,c,i,j,l/), 5, sidx(29)%dims, sidx(29)%chain))
