                        jdet = sidx(104)%perm(jj); w = bt4b_excits(jdet,3); u = bt4b_excits(jdet,5); v = bt4b_excits(jdet,8)
                        IX(:) = IX(:) + (-1d0 * bt4b_amps(jdet)) * V2B_oovv_3012(:,u,v,w)
                     end do
                     end if
                     idx = lk(4)
                     if (idx/=0) then
                     do jj = sidx(105)%off(idx), sidx(105)%off(idx+1)-1
                        jdet = sidx(105)%perm(jj); w = bt4b_excits(jdet,2); u = bt4b_excits(jdet,7); v = bt4b_excits(jdet,8)
                        IX(:) = IX(:) + (1d0 * bt4b_amps(jdet)) * V2B_oovv_3012(:,u,v,w)
                     end do
                     end if
                     idx = lk(5)
                     if (idx/=0) then
                     do jj = sidx(106)%off(idx), sidx(106)%off(idx+1)-1
                        jdet = sidx(106)%perm(jj); w = bt4b_excits(jdet,2); u = bt4b_excits(jdet,6); v = bt4b_excits(jdet,8)
                        IX(:) = IX(:) + (-1d0 * bt4b_amps(jdet)) * V2B_oovv_3012(:,u,v,w)
                     end do
                     end if
                     idx = lk(6)
                     if (idx/=0) then
                     do jj = sidx(107)%off(idx), sidx(107)%off(idx+1)-1
                        jdet = sidx(107)%perm(jj); w = bt4b_excits(jdet,2); u = bt4b_excits(jdet,5); v = bt4b_excits(jdet,8)
                        IX(:) = IX(:) + (1d0 * bt4b_amps(jdet)) * V2B_oovv_3012(:,u,v,w)
                     end do
                     end if
                     idx = lk(7)
                     if (idx/=0) then
                     do jj = sidx(108)%off(idx), sidx(108)%off(idx+1)-1
                        jdet = sidx(108)%perm(jj); w = bt4b_excits(jdet,1); u = bt4b_excits(jdet,7); v = bt4b_excits(jdet,8)
                        IX(:) = IX(:) + (-1d0 * bt4b_amps(jdet)) * V2B_oovv_3012(:,u,v,w)
                     end do
                     end if
                     idx = lk(8)
                     if (idx/=0) then
                     do jj = sidx(109)%off(idx), sidx(109)%off(idx+1)-1
                        jdet = sidx(109)%perm(jj); w = bt4b_excits(jdet,1); u = bt4b_excits(jdet,6); v = bt4b_excits(jdet,8)
                        IX(:) = IX(:) + (1d0 * bt4b_amps(jdet)) * V2B_oovv_3012(:,u,v,w)
                     end do
                     end if
                     idx = lk(9)
                     if (idx/=0) then
                     do jj = sidx(110)%off(idx), sidx(110)%off(idx+1)-1
                        jdet = sidx(110)%perm(jj); w = bt4b_excits(jdet,1); u = bt4b_excits(jdet,5); v = bt4b_excits(jdet,8)
                        IX(:) = IX(:) + (-1d0 * bt4b_amps(jdet)) * V2B_oovv_3012(:,u,v,w)
                     end do
                     end if
                     idx = lk(10)
                     if (idx/=0) then
                     do jj = sidx(111)%off(idx), sidx(111)%off(idx+1)-1
                        jdet = sidx(111)%perm(jj); w = bt4c_excits(jdet,4); u = bt4c_excits(jdet,7); v = bt4c_excits(jdet,8)
                        IX(:) = IX(:) + (1d0 * bt4c_amps(jdet)) * V2C_oovv_3012(:,u,v,w)
                     end do
                     end if
                     idx = lk(11)
                     if (idx/=0) then
                     do jj = sidx(112)%off(idx), sidx(112)%off(idx+1)-1
                        jdet = sidx(112)%perm(jj); w = bt4c_excits(jdet,3); u = bt4c_excits(jdet,7); v = bt4c_excits(jdet,8)
                        IX(:) = IX(:) + (-1d0 * bt4c_amps(jdet)) * V2C_oovv_3012(:,u,v,w)
                     end do
                     end if
                     do idet = toff(kdx), toff(kdx+1)-1
                        c = t4c_excits(idet,3); k = t4c_excits(idet,7); l = t4c_excits(idet,8);
                        val = 0.0d0
                        do x = 1, nub
                           val = val + IX(x) * t2c(x,c,l,k)
                        end do
                        resid(idet) = resid(idet) + 1d0 * val
                     end do
                  end do
                  !$omp end do
                  deallocate(IX)
                  !$omp end parallel
                  deallocate(sidx)
                  deallocate(pidx)
                  deallocate(bt4b_amps,bt4b_excits)
                  deallocate(bt4c_amps,bt4c_excits)
                  deallocate(bt4d_amps,bt4d_excits)
